def {{fn_name}}(s):
    n = len(s)
    if n < 2: return s
    start, max_len = 0, 1
    dp = [[False]*n for _ in range(n)]
    for i in range(n): dp[i][i] = True
    for L in range(2, n+1):
        for i in range(n - L + 1):
            j = i + L - 1
            if s[i] == s[j] and (L == 2 or dp[i+1][j-1]):
                dp[i][j] = True
                if L > max_len:
                    start, max_len = i, L
    return s[start:start+max_len]
